#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets up Cadence's Notification workflows in Knock's Development environment.
# Each Notification kind is one Knock workflow with its own preference
# category; app/lib/notifications.knock.server.ts maps kinds to these keys.
# Run from anywhere: bash scripts/knock-wizard.sh
#
# To add a Notification kind: add one stage + workflow_stage call below (key,
# category, template), add it to the verify stage, and bump TOTAL_STAGES.

cd "$(dirname "$0")/.."

TOTAL_STAGES=9

_env_value() { _existing "$1" | sed -e 's/^"//' -e 's/"$//'; }
SK=$(_env_value KNOCK_SECRET_API_KEY || true)
CH=$(_env_value KNOCK_FEED_CHANNEL_ID || true)
if [[ -z "$SK" || -z "$CH" ]]; then
  printf '%sKNOCK_SECRET_API_KEY / KNOCK_FEED_CHANNEL_ID missing from %s%s\n' "$RED" "$ENV_FILE" "$RESET"
  exit 1
fi
command -v jq >/dev/null 2>&1 || { printf '%sThis wizard needs jq.%s\n' "$RED" "$RESET"; exit 1; }
KNOCK_API="https://api.knock.app/v1"
DASHBOARD="https://dashboard.knock.app"
PROBE_USER="wizard-probe"

# trigger WORKFLOW RECIPIENT: prints the HTTP status of a trigger. The data
# covers every field any Cadence workflow template reads.
trigger() {
  curl -s -o /dev/null -w '%{http_code}' -X POST \
    -H "Authorization: Bearer $SK" -H "Content-Type: application/json" \
    -d "{\"recipients\":[{\"id\":\"$2\",\"name\":\"Wizard Check\"}],\"actor\":{\"id\":\"wizard-actor\",\"name\":\"Wizard\"},\"data\":{\"commentId\":0,\"questionId\":0,\"lessonId\":0,\"lessonTitle\":\"Wizard lesson\",\"snippet\":\"Wizard snippet\",\"seatId\":0,\"courseId\":0,\"courseTitle\":\"Wizard course\",\"seatsLeft\":0,\"enrollmentId\":0,\"refundRequestId\":0,\"buyerName\":\"Wizard buyer\",\"amount\":\"0.00\",\"reason\":\"Wizard reason\",\"purchaseKind\":\"individual_purchase\",\"decisionNote\":\"Wizard note\",\"url\":\"/\"}}" \
    "$KNOCK_API/workflows/$1/trigger"
}

delete_user() {
  curl -s -o /dev/null -X DELETE -H "Authorization: Bearer $SK" "$KNOCK_API/users/$1" || true
}

# check_workflow KEY: loops until the workflow is triggerable or the human gives up.
check_workflow() {
  local status
  while true; do
    status=$(trigger "$1" "$PROBE_USER")
    if [[ "$status" == 2* ]]; then
      printf '  %s✓ %s is committed and triggerable%s\n' "$GREEN" "$1" "$RESET"
      return 0
    fi
    warn "trigger $1 returned HTTP $status (404 = not found or not committed)"
    confirm "Fix it in the dashboard, then retry?" || { SKIPPED+=("workflow $1 (trigger returned $status)"); return 0; }
  done
}

# workflow_stage KEY CATEGORY TEMPLATE
workflow_stage() {
  say "Create (or fix) the ${BOLD}$1${RESET} workflow in the ${BOLD}Development${RESET} environment."
  open_url "$DASHBOARD"
  step "Make sure the environment switcher (top left) says Development."
  step "Workflows. If '$1' already exists, open it; otherwise Create workflow,"
  note "    name it '$1'; the key must be exactly: $1"
  step "Categories: exactly one, '$2'. Remove any other category (e.g. an old 'discussion')."
  step "Steps: one In-app feed step on the 'Cadence feed' channel. No batch, delay or branch:"
  note "    a later ticket adds an email step after it."
  step "Open the step's template and set the markdown body to:"
  printf '\n      %s%s%s\n\n' "$BOLD" "$3" "$RESET"
  note "    Cadence writes the row from the trigger data; Knock just needs a body."
  step "Save, then Commit (top right) to Development."
  note "UI labels may differ slightly; what matters is the key, category, channel and commit."
  pause "Press Enter once it's committed, and I'll check it..."
  check_workflow "$1"
  pause "Press Enter to continue"
}

# verify_workflow KEY CATEGORY: triggers KEY to a throwaway user and checks it
# lands in the feed under CATEGORY.
verify_workflow() {
  local user="wizard-check-$(date +%s)-$1" feed entry categories
  note "$1 → HTTP $(trigger "$1" "$user")"
  for _ in $(seq 1 10); do
    sleep 2
    feed=$(curl -s -H "Authorization: Bearer $SK" "$KNOCK_API/users/$user/feeds/$CH")
    entry=$(jq -c --arg k "$1" '[(.entries // [])[] | select(.source.key==$k)][0] // empty' <<<"$feed")
    [[ -n "$entry" ]] && break
  done
  if [[ -z "$entry" ]]; then
    warn "$1 did NOT land in the feed: check the In-app feed step uses 'Cadence feed'"
    SKIPPED+=("$1 not reaching the feed")
  else
    categories=$(jq -r '.source.categories | join(",")' <<<"$entry")
    if [[ "$categories" == "$2" ]]; then
      printf '  %s✓ %s landed in the feed, category %s%s\n' "$GREEN" "$1" "$2" "$RESET"
    else
      warn "$1 landed, but its categories are '$categories', not '$2'"
      SKIPPED+=("$1 category should be exactly '$2' (is '$categories'); fix and re-commit")
    fi
  fi
  delete_user "$user"
}

banner "Knock setup: Cadence Notification workflows"

stage "Workflow: discussion-reply"
workflow_stage "discussion-reply" "discussion-replies" '**{{ actor.name }}** replied to your question in {{ data.lessonTitle }}'

stage "Workflow: seat-claimed"
workflow_stage "seat-claimed" "seat-claims" '**{{ actor.name }}** claimed a seat on {{ data.courseTitle }}. {{ data.seatsLeft }} left.'

stage "Workflow: discussion-question"
workflow_stage "discussion-question" "discussion-questions" '**{{ actor.name }}** asked a question in {{ data.lessonTitle }}'

stage "Workflow: refund-requested"
workflow_stage "refund-requested" "refund-request-updates" 'We are reviewing your {{ data.amount }} refund request for {{ data.courseTitle }}.'

stage "Workflow: refund-approved"
workflow_stage "refund-approved" "refund-request-updates" 'Your refund for {{ data.courseTitle }} was approved.'

stage "Workflow: refund-declined"
workflow_stage "refund-declined" "refund-request-updates" 'Your refund for {{ data.courseTitle }} was declined.'

stage "Workflow: refund-request-open"
workflow_stage "refund-request-open" "open-refund-requests" '**{{ data.buyerName }}** asked for a {{ data.amount }} refund on {{ data.courseTitle }}.'

stage "Workflow: new-enrollment"
workflow_stage "new-enrollment" "enrollments" '**{{ actor.name }}** enrolled in {{ data.courseTitle }}.'

stage "Verify end to end"
say "Triggering each workflow to a throwaway user and reading its feed (up to ~20s each)..."
verify_workflow "discussion-reply" "discussion-replies"
verify_workflow "seat-claimed" "seat-claims"
verify_workflow "discussion-question" "discussion-questions"
verify_workflow "refund-requested" "refund-request-updates"
verify_workflow "refund-approved" "refund-request-updates"
verify_workflow "refund-declined" "refund-request-updates"
verify_workflow "refund-request-open" "open-refund-requests"
verify_workflow "new-enrollment" "enrollments"
delete_user "$PROBE_USER"
delete_user "wizard-actor"
note "Cleaned up throwaway Knock users."
pause "Press Enter to finish"

finish
